"""Move pending changelog details into the version generated by Release Please."""

import argparse
from pathlib import Path
import re
import tomllib


_RELEASE = re.compile(r"^## \[([^\]]+)\].*$", re.MULTILINE)


def roll_over(changelog: str, version: str) -> str:
    """Return a changelog with one top-level Unreleased section and released details.

    Args:
        changelog: Changelog containing the release heading generated by Release Please.
        version: Version whose release heading receives the pending details.

    Returns:
        Updated changelog. Repeated execution with no pending details is stable.

    Raises:
        ValueError: Release heading is missing or Unreleased appears more than once.
    """
    headings = list(_RELEASE.finditer(changelog))
    pending = [heading for heading in headings if heading[1] == "Unreleased"]
    releases = [heading for heading in headings if heading[1] == version]
    if len(releases) != 1 or len(pending) > 1:
        raise ValueError("Expected one release heading and at most one Unreleased section")
    sections = []
    details = ""
    for index, heading in enumerate(headings):
        end = headings[index + 1].start() if index + 1 < len(headings) else len(changelog)
        body = changelog[heading.end() : end].strip()
        if heading[1] == "Unreleased":
            details = body
        else:
            sections.append((heading[1], changelog[heading.start() : end].rstrip()))
    preamble = changelog[: headings[0].start()].rstrip()
    output = [preamble, "## [Unreleased]"]
    for name, section in sections:
        if name == version and details:
            section += f"\n\n{details}"
        output.append(section)
    return "\n\n".join(output) + "\n"


def main() -> None:
    """Consume pending notes for the project version on the generated release PR."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--changelog", type=Path, default=Path("CHANGELOG.md"))
    args = parser.parse_args()
    version = tomllib.loads(Path("pyproject.toml").read_text())["project"]["version"]
    args.changelog.write_text(roll_over(args.changelog.read_text(), version))


if __name__ == "__main__":
    main()
